css:
.print-format { padding: 0 !important; }
.smr-pass { max-width: 560px; margin: 0 auto; font-size: 13px; color: #111; }
.smr-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; border-bottom: 2px solid #111; padding-bottom: 8px; }
.smr-title { font-size: 18px; font-weight: 700; letter-spacing: .5px; }
.smr-co { font-size: 11px; color: #555; }
.smr-no { font-size: 22px; font-weight: 700; margin-top: 6px; }
.smr-status { display: inline-block; margin-top: 4px; padding: 1px 8px; border-radius: 10px; background: #eee; font-size: 11px; font-weight: 600; }
.smr-approved, .smr-out { background: #dbeafe; } .smr-overdue, .smr-escalated { background: #fee2e2; } .smr-returned { background: #dcfce7; }
.smr-qr { width: 120px; height: 120px; }
.smr-warn { margin: 8px 0; padding: 8px; border: 2px solid #b91c1c; color: #b91c1c; font-weight: 700; text-align: center; }
.smr-meta { width: 100%; margin: 10px 0; border-collapse: collapse; }
.smr-meta th { width: 34%; text-align: left; color: #555; font-weight: 500; padding: 3px 0; vertical-align: top; }
.smr-meta td { padding: 3px 0; }
.smr-items { width: 100%; border-collapse: collapse; font-size: 12px; }
.smr-items th, .smr-items td { border: 1px solid #999; padding: 4px; text-align: left; vertical-align: top; }
.smr-items th { background: #f3f3f3; }
.smr-nw { white-space: nowrap; }
.smr-remarks, .smr-note { margin-top: 8px; font-size: 11px; }
.smr-note { font-style: italic; color: #444; }
.smr-exit { margin-top: 10px; font-size: 11px; }
.smr-photo { display: block; max-width: 100%; max-height: 260px; margin-top: 6px; border: 1px solid #ccc; }
.smr-sign { width: 100%; margin-top: 36px; font-size: 11px; }
.smr-sign td { width: 50%; border-top: 1px solid #555; padding-top: 4px; }
@media screen and (max-width: 600px) { .smr-pass { font-size: 15px; } .smr-qr { width: 96px; height: 96px; } }
